create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to authenticated;
create or replace function private.is_hadassa_admin() returns boolean language sql stable security definer set search_path = '' as $$ select exists(select 1 from public.hadassa_admin_users a where a.user_id=(select auth.uid()) and a.is_active=true); $$;
create or replace function private.is_hadassa_super_admin() returns boolean language sql stable security definer set search_path = '' as $$ select exists(select 1 from public.hadassa_admin_users a where a.user_id=(select auth.uid()) and a.role='super_admin' and a.is_active=true); $$;
create or replace function private.has_hadassa_permission(permission_key text) returns boolean language sql stable security definer set search_path = '' as $$ select exists(select 1 from public.hadassa_admin_users a where a.user_id=(select auth.uid()) and a.is_active=true and (a.role='super_admin' or a.permissions -> permission_key = 'true'::jsonb)); $$;
create or replace function private.guard_hadassa_invite_claim() returns trigger language plpgsql set search_path = '' as $$
begin
 if old.user_id is null and new.user_id=(select auth.uid()) then
  if new.email is distinct from old.email or new.role is distinct from old.role or new.permissions is distinct from old.permissions or new.is_active is distinct from old.is_active then
   raise exception 'Les droits de l’invitation ne peuvent pas être modifiés pendant son activation.';
  end if;
 end if;
 return new;
end; $$;
revoke all on function private.is_hadassa_admin() from public,anon;
revoke all on function private.is_hadassa_super_admin() from public,anon;
revoke all on function private.has_hadassa_permission(text) from public,anon;
revoke all on function private.guard_hadassa_invite_claim() from public,anon;
grant execute on function private.is_hadassa_admin() to authenticated;
grant execute on function private.is_hadassa_super_admin() to authenticated;
grant execute on function private.has_hadassa_permission(text) to authenticated;
grant execute on function private.guard_hadassa_invite_claim() to authenticated;
drop policy if exists "HADASSA admins can read admin accounts" on public.hadassa_admin_users;
drop policy if exists "HADASSA super admins can insert admin accounts" on public.hadassa_admin_users;
drop policy if exists "HADASSA super admins can update admin accounts" on public.hadassa_admin_users;
drop policy if exists "HADASSA super admins can delete admin accounts" on public.hadassa_admin_users;
drop policy if exists "HADASSA editors can insert site content" on public.hadassa_site_content;
drop policy if exists "HADASSA editors can update site content" on public.hadassa_site_content;
drop policy if exists "HADASSA editors can delete site content" on public.hadassa_site_content;
drop policy if exists "HADASSA admins can read audit log" on public.hadassa_admin_audit_log;
drop policy if exists "HADASSA admins can write audit log" on public.hadassa_admin_audit_log;
drop policy if exists "HADASSA admins can read all media assets" on public.media_assets;
drop policy if exists "HADASSA admins can insert media assets" on public.media_assets;
drop policy if exists "HADASSA admins can update media assets" on public.media_assets;
drop policy if exists "HADASSA admins can delete media assets" on public.media_assets;
drop policy if exists "HADASSA admins can update rotation slots" on public.media_rotation_slots;
drop policy if exists "HADASSA admins can upload media files" on storage.objects;
drop policy if exists "HADASSA admins can update media files" on storage.objects;
drop policy if exists "HADASSA admins can delete media files" on storage.objects;
drop function if exists public.bootstrap_hadassa_super_admin() cascade;
drop function if exists public.claim_hadassa_admin_invite() cascade;
drop function if exists public.has_hadassa_permission(text) cascade;
drop function if exists public.is_hadassa_admin() cascade;
drop function if exists public.is_hadassa_super_admin() cascade;
drop trigger if exists hadassa_guard_invite_claim on public.hadassa_admin_users;
create trigger hadassa_guard_invite_claim before update on public.hadassa_admin_users for each row execute function private.guard_hadassa_invite_claim();
create policy "HADASSA admins can read admin accounts" on public.hadassa_admin_users for select to authenticated using(user_id=(select auth.uid()) or email=lower(coalesce((select auth.jwt()->>'email'),'')) or (select private.is_hadassa_super_admin()));
create policy "HADASSA super admins can insert admin accounts" on public.hadassa_admin_users for insert to authenticated with check((select private.is_hadassa_super_admin()) or (email='drivelinkxv76@gmail.com' and email=lower((select auth.jwt()->>'email')) and user_id=(select auth.uid()) and role='super_admin'));
create policy "HADASSA super admins can update admin accounts" on public.hadassa_admin_users for update to authenticated using((select private.is_hadassa_super_admin()) or (email='drivelinkxv76@gmail.com' and email=lower((select auth.jwt()->>'email')) and (user_id is null or user_id=(select auth.uid()))) or (email=lower((select auth.jwt()->>'email')) and email<>'drivelinkxv76@gmail.com' and is_active=true and (user_id is null or user_id=(select auth.uid())))) with check((select private.is_hadassa_super_admin()) or (email='drivelinkxv76@gmail.com' and email=lower((select auth.jwt()->>'email')) and user_id=(select auth.uid()) and role='super_admin') or (email=lower((select auth.jwt()->>'email')) and email<>'drivelinkxv76@gmail.com' and user_id=(select auth.uid()) and role in ('admin','editor') and is_active=true));
create policy "HADASSA super admins can delete admin accounts" on public.hadassa_admin_users for delete to authenticated using((select private.is_hadassa_super_admin()));
create policy "HADASSA editors can insert site content" on public.hadassa_site_content for insert to authenticated with check((select private.has_hadassa_permission('content.manage')));
create policy "HADASSA editors can update site content" on public.hadassa_site_content for update to authenticated using((select private.has_hadassa_permission('content.manage'))) with check((select private.has_hadassa_permission('content.manage')));
create policy "HADASSA editors can delete site content" on public.hadassa_site_content for delete to authenticated using((select private.has_hadassa_permission('content.manage')));
create policy "HADASSA admins can read audit log" on public.hadassa_admin_audit_log for select to authenticated using((select private.is_hadassa_admin()));
create policy "HADASSA admins can write audit log" on public.hadassa_admin_audit_log for insert to authenticated with check(actor_user_id=(select auth.uid()) and (select private.is_hadassa_admin()));
create policy "HADASSA admins can read all media assets" on public.media_assets for select to authenticated using((select private.has_hadassa_permission('media.manage')));
create policy "HADASSA admins can insert media assets" on public.media_assets for insert to authenticated with check((select private.has_hadassa_permission('media.manage')));
create policy "HADASSA admins can update media assets" on public.media_assets for update to authenticated using((select private.has_hadassa_permission('media.manage'))) with check((select private.has_hadassa_permission('media.manage')));
create policy "HADASSA admins can delete media assets" on public.media_assets for delete to authenticated using((select private.has_hadassa_permission('media.manage')));
create policy "HADASSA admins can update rotation slots" on public.media_rotation_slots for update to authenticated using((select private.has_hadassa_permission('media.manage'))) with check((select private.has_hadassa_permission('media.manage')));
create policy "HADASSA admins can upload media files" on storage.objects for insert to authenticated with check(bucket_id='hadassa-media' and (select private.has_hadassa_permission('media.manage')));
create policy "HADASSA admins can update media files" on storage.objects for update to authenticated using(bucket_id='hadassa-media' and (select private.has_hadassa_permission('media.manage'))) with check(bucket_id='hadassa-media' and (select private.has_hadassa_permission('media.manage')));
create policy "HADASSA admins can delete media files" on storage.objects for delete to authenticated using(bucket_id='hadassa-media' and (select private.has_hadassa_permission('media.manage')));
grant select,insert,update,delete on public.hadassa_admin_users to authenticated;
grant select,insert,update,delete on public.hadassa_site_content to authenticated;
grant select on public.hadassa_site_content to anon;
grant select,insert on public.hadassa_admin_audit_log to authenticated;
grant usage,select on sequence public.hadassa_admin_audit_log_id_seq to authenticated;
